// generar_315_fix_peso_cachorro_y_fecha_futura.js
// CHIQUI Entre Señales — Dos correcciones: peso en cachorros + fecha futura
//
// BUG 1 — Peso de cachorros marcado como observación:
//   En cachorros/gatitos, aumentar de peso es parte del crecimiento
//   normal, pero se marcaba en amarillo como "observación" (igual que en
//   un adulto). Ahora, en perros de menos de 18 meses y gatos de menos
//   de 12 meses, el AUMENTO de peso se muestra en verde como dato de
//   crecimiento ("Ha aumentado X kg, parte de su crecimiento"), no como
//   alerta. La PÉRDIDA de peso sí sigue alertando aunque sea cachorro.
//   (Afecta tanto a Salud como a la vista del veterinario, porque ambas
//   usan el mismo componente PesoTracker.)
//
// BUG 2 — Se podía registrar en fecha futura en el calendario:
//   Aunque los días futuros salen deshabilitados, si seleccionabas un
//   día válido (hoy/ayer) y luego cambiabas de mes, ese día se
//   "arrastraba" al nuevo mes y podía quedar en una fecha futura
//   registrable. Ahora:
//     · Al cambiar de mes (flechas o selector) se deselecciona el día.
//     · El panel de registro solo se abre si el día seleccionado NO es
//       futuro (blindaje extra por cualquier camino).
//
// Archivos:
//   · components/PesoTracker.tsx   (peso según edad)
//   · app/calendario/page.tsx      (no registrar a futuro)
//
// No hay SQL.
//
// Uso:
//   node generar_315_fix_peso_cachorro_y_fecha_futura.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "components/PesoTracker.tsx",
    base64: ""
  },
  {
    ruta: "app/calendario/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
